package main

import (
	"fmt"
	"strings"
)

// parse_expression compresses a string using run-length encoding.
// Consecutive identical characters are replaced by the character followed by its count.
// Runs of length 1 omit the count.
func parse_expression(s string) string {
	if len(s) == 0 {
		return ""
	}

	var b strings.Builder
	runChar := s[0]
	runLen := 1

	for i := 1; i < len(s); i++ {
		if s[i] == runChar {
			runLen++
		} else {
			writeRun(&b, runChar, runLen)
			runChar = s[i]
			runLen = 1
		}
	}
	writeRun(&b, runChar, runLen)

	return b.String()
}

func writeRun(b *strings.Builder, ch byte, count int) {
	b.WriteByte(ch)
	if count > 1 {
		fmt.Fprintf(b, "%d", count)
	}
}

package main

import "testing"

func TestParseExpression(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  string
	}{
		// Basic cases
		{"empty string", "", ""},
		{"single char", "a", "a"},
		{"two identical", "aa", "a2"},
		{"three identical", "aaa", "a3"},

		// No consecutive repeats
		{"all distinct", "abcdef", "abcdef"},
		{"alternating", "abab", "abab"},
		{"alternating triple", "abcabc", "abcabc"},

		// Mixed runs
		{"classic example", "aaabbccccdd", "a3b2c4d2"},
		{"single between runs", "aaabcaaa", "a3b1c1a3"},
		{"run then single", "aab", "a2b"},
		{"single then run", "abb", "ab2"},

		// Longer runs
		{"ten identical", "aaaaaaaaaa", "a10"},
		{"run of 12", "bbbbbbbbbbbb", "b12"},
		{"mixed with long run", "aaabbbbbbbbbbbbcccc", "a3b12c4"},

		// Different character types
		{"digits", "11122233", "132232"},
		{"spaces", "   aa  ", " 3a2 2"},
		{"mixed alphanumeric", "aa11bb22", "a212b22"},
		{"special chars", "!!@@@", "!2@3"},
		{"unicode-like bytes", "aabbaa", "a2b2a2"},

		// Whitespace
		{"tab chars", "\t\t\t", "\t3"},
		{"newline chars", "\n\na\n", "\n2a1\n"},

		// Edge: single long run
		{"run of 100", string(make([]byte, 100)), string(append([]byte{0}, []byte("100")...))},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := parse_expression(tt.input)
			if got != tt.want {
				t.Errorf("parse_expression(%q) = %q, want %q", tt.input, got, tt.want)
			}
		})
	}
}

func TestParseExpressionRoundtrip(t *testing.T) {
	// Verify that the output is never longer than the input
	inputs := []string{
		"aaabbccccdd",
		"abcdef",
		"aaaaaaaaaa",
		"a",
		"",
		"abababab",
	}
	for _, s := range inputs {
		compressed := parse_expression(s)
		if len(compressed) > len(s) {
			t.Errorf("parse_expression(%q) = %q is longer than input (len %d > %d)",
				s, compressed, len(compressed), len(s))
		}
	}
}

func TestParseExpressionDeterministic(t *testing.T) {
	// Calling twice on the same input must produce the same output
	inputs := []string{"aaabbb", "abcdef", "aabbcc", ""}
	for _, s := range inputs {
		first := parse_expression(s)
		second := parse_expression(s)
		if first != second {
			t.Errorf("non-deterministic: parse_expression(%q) gave %q then %q", s, first, second)
		}
	}
}
